def expected_score(n, k):
    # dp[i][j] will store the maximum expected value when there are i rolls left and j sides of the die
    dp = [[0.0] * (n + 1) for _ in range(k + 1)]

    for i in range(1, k + 1):
        for j in range(1, n + 1):
            if i == 1:
                # With one roll, the expected score is the average of all possible scores
                dp[i][j] = (j + 1) / 2
            else:
                # Calculate expected score by taking the maximum expected score of stopping or rerolling
                dp[i][j] = (j + 1) / 2  # Option to stop
                for x in range(1, j + 1):
                    dp[i][j] = max(dp[i][j], x + (dp[i - 1][j] - x) / j)

    # The answer will be in dp[k][n]
    return dp[k][n]

