def expected_score(n, k):
    # dp[roll][max_roll] will store the expected score when rolled roll times
    # with the maximum score being max_roll.
    dp = [[0.0] * (k + 1) for _ in range(k + 1)]

    # Base case: With 0 rolls, the expected score is 0.
    for max_roll in range(k + 1):
        dp[0][max_roll] = 0.0

    # Fill the DP table
    for roll in range(1, k + 1):
        for max_roll in range(1, k + 1):
            expected_value = 0.0
            for face in range(1, n + 1):
                if face <= max_roll:
                    expected_value += face / n * dp[roll - 1][max_roll]
                else:
                    expected_value += face / n * (face / n)
            dp[roll][max_roll] = expected_value

    # The result is the maximum expected score we can get by rolling up to k times.
    return max(dp[roll][k] for roll in range(1, k + 1))

